<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Fechamento Integrado — Liceu Brasil</title><style>*{box-sizing:border-box}body{margin:0;background:#eef6fc;color:#0b2c54;font-family:Inter,Segoe UI,Arial,sans-serif}.page{max-width:1320px;margin:auto;padding:26px}.hero{background:linear-gradient(115deg,#052f6c,#087cba);color:white;border-radius:24px;padding:32px}.brand{letter-spacing:4px;font-weight:900}.hero h1{font-size:clamp(28px,4vw,43px);margin:14px 0 3px}.month{color:#9af0ff;font-weight:900;font-size:23px}.hero p{color:#dceeff}.section{margin:28px 2px 12px;font-size:20px;font-weight:900}.section:before{content:' ';display:inline-block;width:7px;height:22px;border-radius:8px;background:#18a9d6;vertical-align:middle;margin-right:10px}.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:14px}.card{grid-column:span 12;background:white;border:1px solid #d8e8f5;border-radius:17px;padding:20px;box-shadow:0 7px 20px #103f7310}.kpi{grid-column:span 3}.half{grid-column:span 6}.kpi .label{font-size:12px;color:#6d8199;font-weight:800}.value{font-size:clamp(24px,2.8vw,35px);font-weight:900;margin:10px 0 6px}.sub{color:#6d8199;font-size:12px}.blue{color:#0875c8}.green{color:#0b9b6b}.red{color:#e04d61}.orange{color:#dc8a14}.title{font-size:18px;font-weight:900;margin:0 0 14px}table{width:100%;border-collapse:collapse;font-size:13px}td,th{padding:10px 7px;border-bottom:1px solid #e4edf5;text-align:left}th{color:#657d97;font-size:11px;text-transform:uppercase}.right{text-align:right}.note{font-size:13px;color:#55708c;line-height:1.65;background:#f0f7ff;border:1px solid #dbeafa;border-radius:12px;padding:13px;margin-top:14px}.warning{background:#fff7e9;border-color:#f7dfb8}.summary{background:#073c80;color:white}.summary p{color:#e1efff;line-height:1.7}.bar{height:11px;background:#e8f1fa;border-radius:15px;overflow:hidden;margin:12px 0}.bar span{display:block;height:100%;background:linear-gradient(90deg,#0a9d72,#42c9d2)}.pill{display:inline-block;border-radius:20px;background:#e7f3fd;color:#246296;padding:5px 10px;font-size:11px;font-weight:800}.foot{text-align:center;color:#8296aa;font-size:11px;padding:25px}@media(max-width:900px){.kpi{grid-column:span 6}.half{grid-column:span 12}}@media(max-width:550px){.page{padding:10px}.kpi{grid-column:span 12}.card{padding:15px}table{font-size:11px}}@media print{body{background:white}.page{padding:0}.card,.hero{break-inside:avoid;box-shadow:none}.hero{print-color-adjust:exact;-webkit-print-color-adjust:exact}}.toolbar{display:flex;flex-wrap:wrap;gap:12px;align-items:end;margin:18px 0}.toolbar label{display:block;font-size:12px;font-weight:800;margin-bottom:5px}.toolbar input,.toolbar select{padding:10px;border:1px solid #c6d9ea;border-radius:9px;max-width:180px}.btn{border:0;border-radius:10px;padding:11px 14px;background:#086db1;color:white;font-weight:800;cursor:pointer}.btn.alt{background:white;color:#075b9d;border:1px solid #b7d2e8}.alert{color:#a52c37;font-weight:800}.wide{overflow:auto}.span4{grid-column:span 4}.span3{grid-column:span 3}.span6{grid-column:span 6}.span12{grid-column:span 12}.empty{color:#879bb0}.meta{font-size:12px;color:#617e9d;margin:9px 0}.mini{font-size:12px;color:#789}.card{min-width:0}@media(max-width:900px){.span4,.span3,.span6{grid-column:span 12}}@media print{.toolbar,.noprint{display:none!important}.page{max-width:none}.card{break-inside:avoid}}</style></head><body><main class="page"><header class="hero"><div class="brand">◇ LICEU BRASIL</div><h1>FECHAMENTO INTEGRADO</h1><div class="month" id="periodoTitulo">RELATÓRIO DINÂMICO</div><p>Comercial • Acompanhamento pedagógico • Financeiro • Cobranças | Indicadores consolidados do sistema</p></header>
<div class="toolbar noprint"><div><label for="inicio">Data inicial</label><input id="inicio" type="date"></div><div><label for="fim">Data final</label><input id="fim" type="date"></div><div><label for="tipoCurso">Tipo de curso (pedagógico)</label><select id="tipoCurso"><option value="todos">Todos</option><option value="pago">Pagos</option><option value="gratuito">Gratuitos</option></select></div><div><label for="ajuste">Ajuste de entradas (R$, opcional)</label><input id="ajuste" type="number" step="0.01" value="0"></div><button class="btn" onclick="carregar()">Gerar relatório</button><button class="btn alt" onclick="window.print()">Salvar PDF</button><button class="btn alt" onclick="whatsapp()">WhatsApp</button><a class="btn alt" href="../" style="text-decoration:none">Central de Apps</a></div>
<div class="meta" id="meta">Selecione o período.</div><div class="alert" id="erro"></div><div id="relatorio"></div><div class="foot" id="rodape">LICEU BRASIL · Fechamento Integrado</div></main><script>
const $=id=>document.getElementById(id),brl=n=>Number(n||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}),num=n=>Number(n||0).toLocaleString('pt-BR'),pct=n=>Number(n||0).toLocaleString('pt-BR',{minimumFractionDigits:1,maximumFractionDigits:1})+'%',esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let atual=null;
function kpi(label,value,sub,cls='blue'){return `<div class="card kpi"><div class="label">${esc(label)}</div><div class="value ${cls}">${esc(value)}</div><div class="sub">${esc(sub||'')}</div></div>`}
function sec(t){return `<div class="section">${esc(t)}</div>`}
function tabela(t,headers,rows,fn,cl='half'){return `<div class="card ${cl}"><div class="title">${esc(t)}</div><div class="wide"><table><thead><tr>${headers.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${fn(r).map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}" class="empty">Sem dados no período</td></tr>`}</tbody></table></div></div>`}
function nota(t){return `<div class="card"><div class="note">${esc(t)}</div></div>`}
function render(j){const c=j.comercial||{},p=j.pedagogico||{},f=j.financeiro||{},b=j.cobranca||{};const mensal=p.acompanhamentoMensal||[],m=mensal.length===1?mensal[0]:null,previstos=m?Number(m.total):null,ajuste=Number($('ajuste').value||0),presentes=m?Number(m.ativos):null,ausentes=m?Number(m.desaparecidos):null,retencao=m?Number(m.taxa):null,formados=m?Number(m.formadosMes):null,cancelados=m?Number(m.canceladosMes):null,mens=p.mensagens;let h='';
h+=sec('Comercial')+'<div class="grid">'+kpi('VISITAS',num(c.visitas),'Visitas registradas no período')+kpi('MATRÍCULAS TOTAIS',num(c.matriculas),`${num(c.pagas)} pagas + ${num(c.gratuitas)} gratuitas`,'green')+kpi('MATRÍCULAS PAGAS',num(c.pagas),'Matrículas comerciais','green')+kpi('CONVERSÃO PAGA',c.conversaoPaga==null?'—':pct(c.conversaoPaga),'Pagas / visitas','green');
h+=tabela('Visitas por origem',['Origem','Visitas'],c.origens||[],x=>[x.origem,num(x.visitas)])+tabela('Resultado por vendedor',['Vendedor','Pagas','Gratuitas','Total'],c.vendedores||[],x=>[x.vendedor,num(x.pagas),num(x.gratuitas),num(x.total)])+tabela('Cursos pagos mais vendidos',['Curso','Pagas'],(c.cursos||[]).filter(x=>Number(x.pagas)>0).sort((a,b)=>b.pagas-a.pagas),x=>[x.curso,num(x.pagas)])+tabela('Cursos gratuitos mais procurados',['Curso','Gratuitas'],(c.cursos||[]).filter(x=>Number(x.gratuitas)>0).sort((a,b)=>b.gratuitas-a.gratuitas),x=>[x.curso,num(x.gratuitas)])+nota('Matrículas comerciais: visita_matriculas criadas no período. Não equivalem a taxas de matrícula recebidas no financeiro. A origem das visitas é inferida dos campos disponíveis no cadastro, podendo agrupar registros não identificados.')+'</div>';
h+=sec('Acompanhamento pedagógico')+'<div class="grid">'+kpi('ALUNOS PREVISTOS',previstos===null?'—':num(previstos),'Acompanhamento do Dia · visão mensal')+kpi('COM PRESENÇA',presentes===null?'—':num(presentes),'Alunos únicos com presença no mês','green')+kpi('SEM PRESENÇA',ausentes===null?'—':num(ausentes),'Previstos sem presença no mês','red')+kpi('TAXA DE RETENÇÃO',retencao===null?'—':pct(retencao),'Presença mensal / previstos','orange');
h+=kpi('FORMADOS NO MÊS',formados===null?'—':num(formados),'Alunos únicos formados no mês','green')+kpi('CANCELADOS NO MÊS',cancelados===null?'—':num(cancelados),'Encerramentos no mês','red')+kpi('MENSAGENS CONFIRMADAS',mens?num(mens.enviados):'—','Contatos de faltosos registrados no período')+kpi('RETORNOS REGISTRADOS',mens?num(Number(mens.respondidos||0)+Number(mens.resolvidos||0)):'—','Respondidos + resolvidos','green');
h+=tabela('Acompanhamento das mensagens',['Situação','Quantidade'],mens?[{s:'Sem retorno',v:mens.sem_retorno},{s:'Retorno pendente',v:mens.pendentes},{s:'Respondido',v:mens.respondidos},{s:'Resolvido',v:mens.resolvidos}]:[],x=>[x.s,num(x.v)])+nota('Mensagens: confirmações manuais registradas no Acompanhamento do Dia, vinculadas à data da falta. Retornos: situação atual do contato, não necessariamente a data em que a resposta chegou. Não equivale a confirmação de entrega pelo WhatsApp.');
h+=`<div class="card half"><div class="title">Retenção acadêmica</div><div class="value green">${retencao===null?'—':pct(retencao)}</div><div class="sub">${presentes===null?'—':num(presentes)} alunos presentes · ${previstos===null?'—':num(previstos)} alunos previstos no mês</div><div class="bar"><span style="width:${Math.max(0,Math.min(100,retencao||0))}%"></span></div><div class="note">Eventos registrados: ${num(p.presencas)} presenças, ${num(p.faltas)} faltas e ${num(p.pendentes)} estados diferentes de presença/falta. São registros, não pessoas.</div></div>`;
h+=`<div class="card half"><div class="title">Metodologia</div><p>Filtro de pagos/gratuitos usa o tipo da turma no Acompanhamento do Dia. Os indicadores vêm automaticamente da mesma base mensal de matrículas válidas e presenças únicas do Acompanhamento do Dia. Selecione um período dentro de um único mês para exibir a retenção mensal.</p><div class="note warning">Ausência de presença não comprova cancelamento ou evasão. Os detalhamentos por curso e turma consideram alunos com chamada; não equivalem à base geral de previstos.</div></div>`;
h+=tabela('Acompanhamento por curso',['Curso','Com chamada','Com presença','Retenção'],p.cursos||[],x=>[x.curso,num(x.alunos),num(x.presentes),Number(x.alunos)>0?pct(100*x.presentes/x.alunos):'—'],'card') ;
const ts=(p.turmas||[]).map(x=>({...x,taxa:Number(x.alunos)>0?100*Number(x.presentes)/Number(x.alunos):0}));h+=tabela('Maiores retenções por turma',['Turma','Professor','Alunos','Retenção'],ts.slice().sort((a,b)=>b.taxa-a.taxa).slice(0,8),x=>[x.turma,x.professor,`${num(x.presentes)} / ${num(x.alunos)}`,pct(x.taxa)])+tabela('Pontos de atenção por turma',['Turma','Professor','Alunos','Retenção'],ts.slice().sort((a,b)=>a.taxa-b.taxa).slice(0,8),x=>[x.turma,x.professor,`${num(x.presentes)} / ${num(x.alunos)}`,pct(x.taxa)])+'</div>';
h+=sec('Financeiro')+'<div class="grid">'+kpi('ENTRADAS NO XML',brl(f.entradas),`${num(f.qtdEntradas)} lançamentos`,'green')+kpi('AJUSTE DE COMPETÊNCIA',brl(ajuste),'Valor manual; subtraído das entradas','orange')+kpi('ENTRADAS AJUSTADAS',brl(Number(f.entradas||0)-ajuste),'Leitura gerencial','green')+kpi('SAÍDAS',brl(f.saidas),`${num(f.qtdSaidas)} lançamentos`,'red')+kpi('SALDO BRUTO NO XML',brl(f.saldo),'Sem ajuste')+kpi('SALDO AJUSTADO',brl(Number(f.saldo||0)-ajuste),'Não representa lucro','green')+kpi('MENSALIDADES NO XML',brl((f.categoriasEntradas||[]).filter(x=>String(x.categoria).toLowerCase().includes('mensalidade')).reduce((a,x)=>a+Number(x.valor),0)),'Categoria mensalidade')+kpi('TAXAS DE MATRÍCULA',brl((f.categoriasEntradas||[]).filter(x=>String(x.categoria).toLowerCase().includes('taxa de matr')).reduce((a,x)=>a+Number(x.valor),0)),'Categoria de receita');
h+=tabela('Entradas — categorias originais',['Categoria','Lançamentos','Valor'],f.categoriasEntradas||[],x=>[x.categoria,num(x.quantidade),brl(x.valor)])+tabela('Saídas — categorias originais',['Categoria','Lançamentos','Valor'],f.categoriasSaidas||[],x=>[x.categoria,num(x.quantidade),brl(x.valor)])+nota('O ajuste de competência é informado manualmente e não altera lançamentos. Entradas e saídas vêm do Analytics Sponte; saldo não é lucro contábil. Transferências, empréstimos e retiradas podem exigir segregação.')+'</div>';
h+=sec('Cobranças — acompanhamento')+'<div class="grid">'+kpi('CONTATOS REALIZADOS',num(b.contatos),'Registros no período')+kpi('ACORDOS FIRMADOS',num(b.acordos),brl(b.valorAcordado)+' programados','orange')+kpi('RECEBIMENTOS INFORMADOS',num(b.recebimentos),'Registros operacionais','green')+kpi('VALOR INFORMADO',brl(b.valorInformado),'Não equivale a conciliação bancária','green');
h+=tabela('Resultados dos contatos',['Resultado','Quantidade'],b.resultados||[],x=>[x.resultado,num(x.quantidade)])+tabela('Situação da carteira de acordos (hoje)',['Situação','Quantidade','Valor'],b.situacoesAcordos||[],x=>[x.situacao,num(x.quantidade),brl(x.valor)]);
const inad=(b.inadimplenciaUltimaImportacao||[])[0];h+=`<div class="card"><div class="title">Inadimplência — última importação</div><div class="value red">${inad?brl(inad.total_aberto):'—'}</div><div class="sub">${inad?num(inad.registros)+' registros • '+num(inad.alunos_vinculados)+' alunos vinculados':'Sem importação disponível'}</div><div class="note warning">Fotografia da última importação Sponte, não necessariamente referente ao período do relatório. Acordos em atraso não são baixados automaticamente por recebimentos informados.</div></div>`+'</div>';
h+=sec('Presença e recebimentos')+'<div class="grid">'+kpi('PRESENTES NO PERÍODO',num(p.alunosPresentes),'Alunos únicos')+kpi('PRESENTES COM MENSALIDADE','—','Cruzamento individual não disponível nesta versão')+kpi('PRESENTES SEM RECEBIMENTO','—','Não presumir inadimplência sem vínculo confirmado')+nota('Para reproduzir os cruzamentos nominais do fechamento de outubro, é necessária uma regra de correspondência validada entre presenças, alunos e lançamentos financeiros; nenhum número foi estimado.')+'</div>';
h+=sec('Síntese executiva')+`<div class="grid"><div class="card summary"><div class="title" style="color:white">Período em uma página</div><p>O comercial registrou ${num(c.visitas)} visitas e ${num(c.matriculas)} matrículas (${num(c.pagas)} pagas e ${num(c.gratuitas)} gratuitas). No pedagógico, ${num(p.alunosPresentes)} alunos únicos tiveram presença registrada${retencao===null?'; a retenção mensal exige um único mês selecionado':', correspondendo a '+pct(retencao)+' da base mensal do Acompanhamento do Dia'}. O financeiro apresentou entradas de ${brl(f.entradas)}, saídas de ${brl(f.saidas)} e saldo ${brl(Number(f.saldo||0)-ajuste)} após ajuste manual de ${brl(ajuste)}. A cobrança realizou ${num(b.contatos)} contatos, firmou ${num(b.acordos)} acordos e registrou ${brl(b.valorInformado)} em recebimentos informados.</p></div></div>`;
$('relatorio').innerHTML=h;$('periodoTitulo').textContent=j.inicio.split('-').reverse().join('/')+' — '+j.fim.split('-').reverse().join('/');$('meta').textContent='Gerado em '+new Date(j.geradoEm).toLocaleString('pt-BR')+' · Fontes: '+Object.values(j.fontes||{}).join(' | ');$('rodape').textContent='LICEU BRASIL · Fechamento Integrado · '+j.inicio+' a '+j.fim+' · Dados do sistema e ajustes gerenciais explicitados';}
async function carregar(){try{$('erro').textContent='';$('meta').textContent='Consultando o banco...';const r=await fetch('api.php?inicio='+encodeURIComponent($('inicio').value)+'&fim='+encodeURIComponent($('fim').value)+'&tipoCurso='+encodeURIComponent($('tipoCurso').value),{cache:'no-store'});const j=await r.json();if(!r.ok||!j.ok)throw Error(j.error||'Falha na consulta');atual=j;render(j)}catch(e){$('erro').textContent=e.message;$('meta').textContent='Falha ao carregar.'}}
function whatsapp(){if(!atual){alert('Gere o relatório primeiro.');return}const j=atual,c=j.comercial,p=j.pedagogico,f=j.financeiro,b=j.cobranca;const a=Number($('ajuste').value||0);const msg=`*LICEU BRASIL | FECHAMENTO INTEGRADO*\n${j.inicio} a ${j.fim}\n\n*COMERCIAL*\nVisitas: ${num(c.visitas)} | Matrículas: ${num(c.matriculas)} (${num(c.pagas)} pagas / ${num(c.gratuitas)} gratuitas)\n\n*PEDAGÓGICO*\nAlunos presentes no mês: ${((p.acompanhamentoMensal||[]).length===1)?num(p.acompanhamentoMensal[0].ativos):'—'} | Presenças: ${num(p.presencas)} | Faltas: ${num(p.faltas)} | Formados: ${((p.acompanhamentoMensal||[]).length===1)?num(p.acompanhamentoMensal[0].formadosMes):'—'} | Mensagens confirmadas: ${p.mensagens?num(p.mensagens.enviados):'—'} | Retornos: ${p.mensagens?num(Number(p.mensagens.respondidos||0)+Number(p.mensagens.resolvidos||0)):'—'}\n\n*FINANCEIRO*\nEntradas: ${brl(f.entradas)} | Saídas: ${brl(f.saidas)} | Ajuste: ${brl(a)} | Saldo ajustado: ${brl(Number(f.saldo||0)-a)}\n\n*COBRANÇAS*\nContatos: ${num(b.contatos)} | Acordos: ${num(b.acordos)} | Recebimentos informados: ${brl(b.valorInformado)}\n\n_Valores sujeitos à conferência de importações, vínculos e ajustes gerenciais._`;window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank','noopener')}
const d=new Date(),local=new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10);$('inicio').value=$('fim').value=local;carregar();
</script></body></html>